(5751628, 835409, 18197, '<td valign="top">Okay, I am an unapologetic fan of astro-photography. This is terrific. I love it. It''s getting a great score.</td>', 'Okay, I am an unapologetic fan of astro-photography. This is terrific. I love it. It''s getting a great score.', '2009-12-03 00:20:40.000000', NULL, 1),
