(5751640, 832041, 18197, '<td valign="top">Love the highly saturated colors here. the composition with the strong shadows and trees and sun is really very very good.</td>', 'Love the highly saturated colors here. the composition with the strong shadows and trees and sun is really very very good.', '2009-12-03 00:31:18.000000', NULL, 1),
(5751641, 836760, 18197, '<td valign="top">You have presented me with a strong rhythm here. I''m not sure what the photo''s subject is, but I resonate with the rhythm.</td>', 'You have presented me with a strong rhythm here. I''m not sure what the photo''s subject is, but I resonate with the rhythm.', '2009-12-03 00:32:35.000000', NULL, 1),
