(5754936, 831846, 18197, '<td valign="top">This feels zen-like ... like a Japanese or Chinese painting. Beautifully done.</td>', 'This feels zen-like ... like a Japanese or Chinese painting. Beautifully done.', '2009-12-04 21:54:14.000000', NULL, 1),
