(5756895, 836828, 83313, '<td valign="top">If you lived in the city, you''d only have to deal with squirrels. And you would have to travel to get your wildlife shots.</td>', 'If you lived in the city, you''d only have to deal with squirrels. And you would have to travel to get your wildlife shots.', '2009-12-06 14:54:15.000000', NULL, 1),
(5756897, 836064, 18197, '<td valign="top">Pretty animal, beautifully composed. Nice detail in the fur and whiskers. Feels a little tilted but it may well be an optical illusion.</td>', 'Pretty animal, beautifully composed. Nice detail in the fur and whiskers. Feels a little tilted but it may well be an optical illusion.', '2009-12-06 14:54:31.000000', NULL, 1),
