(5757280, 836034, 18197, '<td valign="top">It would be fun to hike this trail. Walking in a snowy wood has a soft peaceful feeling which contrasts somewhat with the herky jerky feeling of the railing. It adds to the dynamic nature of the scene.</td>', 'It would be fun to hike this trail. Walking in a snowy wood has a soft peaceful feeling which contrasts somewhat with the herky jerky feeling of the railing. It adds to the dynamic nature of the scene.', '2009-12-06 20:48:48.000000', NULL, 1),
(5757281, 836175, 18197, '<td valign="top">Lovely colors. Like the sky and its reflection.</td>', 'Lovely colors. Like the sky and its reflection.', '2009-12-06 20:49:17.000000', NULL, 1),
(5757282, 835522, 18197, '<td valign="top">Beautiful sky detail. I love it when clouds are lit by reflected light from below like this.</td>', 'Beautiful sky detail. I love it when clouds are lit by reflected light from below like this.', '2009-12-06 20:49:59.000000', NULL, 1),
(5757288, 836044, 18197, '<td valign="top">What a pretty place. The light coming through the glass is so unusual. You''ve picked it up in the sky reflections and in the sky itself. Superb. Greens and reds my be a little hot but they offer effective color contrast ... I''m not sure i''d change them much ... if at all.</td>', 'What a pretty place. The light coming through the glass is so unusual. You''ve picked it up in the sky reflections and in the sky itself. Superb. Greens and reds my be a little hot but they offer effective color contrast ... I''m not sure i''d change them much ... if at all.', '2009-12-06 20:52:07.000000', NULL, 1),
(5757295, 834504, 18197, '<td valign="top">This would be a treasured addition to any wedding album. Selective desat takes us back in time. Color brings us back to today.</td>', 'This would be a treasured addition to any wedding album. Selective desat takes us back in time. Color brings us back to today.', '2009-12-06 20:54:19.000000', NULL, 1),
(5757297, 836638, 18197, '<td valign="top">Lovely. Sand Hill Cranes I presume. Neat you caught several together like this.</td>', 'Lovely. Sand Hill Cranes I presume. Neat you caught several together like this.', '2009-12-06 20:55:17.000000', NULL, 1),
(5757299, 831706, 18197, '<td valign="top">Beautifully detailed shot. Better than most of the shots in the bird book I use most often as a reference. Professional. Publishable.</td>', 'Beautifully detailed shot. Better than most of the shots in the bird book I use most often as a reference. Professional. Publishable.', '2009-12-06 20:56:16.000000', NULL, 1),
(5757301, 835871, 18197, '<td valign="top">Gives me the feeling REAL work is going on here. Lighting, darks, lights, contrast are effective at taking my eye exactly where you want it to go. Good work.</td>', 'Gives me the feeling REAL work is going on here. Lighting, darks, lights, contrast are effective at taking my eye exactly where you want it to go. Good work.', '2009-12-06 20:57:30.000000', NULL, 1),
