(5757315, 835204, 18197, '<td valign="top">This is just lovely. Sharp and soft focus are really effective. Color is very very good. Border works. Among best of show.</td>', 'This is just lovely. Sharp and soft focus are really effective. Color is very very good. Border works. Among best of show.', '2009-12-06 21:03:56.000000', NULL, 1),
(5757317, 836771, 18197, '<td valign="top">The scene is fine but if the focus were a bit more precise and the shadow detail a bit more apparent, I would probably like it better.</td>', 'The scene is fine but if the focus were a bit more precise and the shadow detail a bit more apparent, I would probably like it better.', '2009-12-06 21:05:02.000000', NULL, 1),
