(5757325, 834546, 18197, '<td valign="top">Lovely abstract shapes. I especially like the way you''ve off set them with a bit of light in the upper left corner. Not so much a fan of this border treatment but it doesn''t hurt in this case.</td>', 'Lovely abstract shapes. I especially like the way you''ve off set them with a bit of light in the upper left corner. Not so much a fan of this border treatment but it doesn''t hurt in this case.', '2009-12-06 21:08:13.000000', NULL, 1),
(5757327, 836735, 18197, '<td valign="top">Nice lighting and reflections. I like that you caught a few stars. Must have been very still to get such perfect reflections.</td>', 'Nice lighting and reflections. I like that you caught a few stars. Must have been very still to get such perfect reflections.', '2009-12-06 21:09:11.000000', NULL, 1),
