(5757394, 835284, 11518, '<td valign="top">Beautiful!  Leaves were redder and it was raining when I went there in mid-November...</td>', 'Beautiful!  Leaves were redder and it was raining when I went there in mid-November...', '2009-12-06 21:59:49.000000', NULL, 1),
(5757405, 833789, 83313, '<td valign="top">Post-vote comment:<br/>I gave this a pretty high vote, I love the incredible detail showing and the good range of B/W tones in it. I''m a sucker for detail and texture. About the only nitpick I might make is a bit of extra empty space at the top of the frame. I would have probably cropped it to try and put his eye in a ROT location. Not always possible, I don''t know what you had to work with out of the camera.</td>', 'Post-vote comment:I gave this a pretty high vote, I love the incredible detail showing and the good range of B/W tones in it. I''m a sucker for detail and texture. About the only nitpick I might make is a bit of extra empty space at the top of the frame. I would have probably cropped it to try and put his eye in a ROT location. Not always possible, I don''t know what you had to work with out of the camera.', '2009-12-06 22:23:07.000000', NULL, 1),
(5757444, 835542, 76335, '<td valign="top">Can''t really see what she''s holding -- I''m guessing she''s about to clobber somebody. Besides that, the textures (or lack thereof) in her face look unnatural.</td>', 'Can''t really see what she''s holding -- I''m guessing she''s about to clobber somebody. Besides that, the textures (or lack thereof) in her face look unnatural.', '2009-12-06 23:06:02.000000', NULL, 1),
(5757446, 836910, 76335, '<td valign="top">Not bad as these cliche shots go. The liquid has a silky quality.</td>', 'Not bad as these cliche shots go. The liquid has a silky quality.', '2009-12-06 23:06:47.000000', NULL, 1),
(5757447, 836663, 76335, '<td valign="top">This would make Arbus proud. Excellent!</td>', 'This would make Arbus proud. Excellent!', '2009-12-06 23:07:32.000000', NULL, 1),
(5757449, 836158, 76335, '<td valign="top">Not blurry enough (or in the right way) to be an intersting abstract. As such, it needs a static object to provide context or just visual relief.</td>', 'Not blurry enough (or in the right way) to be an intersting abstract. As such, it needs a static object to provide context or just visual relief.', '2009-12-06 23:10:41.000000', NULL, 1),
