(5757700, 836563, 67258, '<td valign="top">A pleasing portrait, but lacking somewhat in textural detail.  I like the pose.</td>', 'A pleasing portrait, but lacking somewhat in textural detail.  I like the pose.', '2009-12-07 04:51:05.000000', NULL, 1),
(5757701, 836840, 67258, '<td valign="top">My attention is grabbed by the rocks of the title, with the strong blue sky and the hint of the moon - and then I spot the snow on the ground; quite unexpected! A pleasing composition, and an interesting landscape, although there does seem to be a bit of a halo around part of the top of the rocks.</td>', 'My attention is grabbed by the rocks of the title, with the strong blue sky and the hint of the moon - and then I spot the snow on the ground; quite unexpected! A pleasing composition, and an interesting landscape, although there does seem to be a bit of a halo around part of the top of the rocks.', '2009-12-07 04:54:00.000000', NULL, 1),
(5757702, 831232, 67258, '<td valign="top">Interesting, and I love the muted colour palette.  Rather wish the bicycle wheels had not been cropped so tight.</td>', 'Interesting, and I love the muted colour palette.  Rather wish the bicycle wheels had not been cropped so tight.', '2009-12-07 04:54:52.000000', NULL, 1),
