(5758059, 836264, 47249, '<td valign="top">Fine b/w! 8</td>', 'Fine b/w! 8', '2009-12-07 12:14:19.000000', NULL, 1),
(5758060, 836813, 61961, '<td valign="top">Of course this is from Alfredo, having seen and admired the ribbon-winning version in another challenge.  I love the exotic location and subjects, however, I think this version suffers from the lighting, which seems too artificial for the setting, and also from the model''s expression, which the close-up reveals is just a bit too posed.  However, overall this is still more interesting than many other more technically perfect entries, so I can''t fault it too much. :-)</td>', 'Of course this is from Alfredo, having seen and admired the ribbon-winning version in another challenge.  I love the exotic location and subjects, however, I think this version suffers from the lighting, which seems too artificial for the setting, and also from the model''s expression, which the close-up reveals is just a bit too posed.  However, overall this is still more interesting than many other more technically perfect entries, so I can''t fault it too much. :-)', '2009-12-07 12:14:38.000000', NULL, 1),
(5758061, 833116, 47249, '<td valign="top">Great moment! 8</td>', 'Great moment! 8', '2009-12-07 12:14:47.000000', NULL, 1),
