INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5758937, 836807, 44877, '<td valign="top">Gorgeous! Great processing. I know those red rocks don''t always cooperate during editing. Awesome image.</td>', 'Gorgeous! Great processing. I know those red rocks don''t always cooperate during editing. Awesome image.', '2009-12-07 20:38:11.000000', NULL, 1),
(5758938, 834603, 70270, '<td valign="top">I am soooooooooooooooo sick of eagle shots, because they are all nearly identical -- Crisp yellow beak in profile, photoshopped eyes, detailed feather array, etc.  But not this one.  Thanks for showing us something different, that captures the bird and not the ideal.  10.</td>', 'I am soooooooooooooooo sick of eagle shots, because they are all nearly identical -- Crisp yellow beak in profile, photoshopped eyes, detailed feather array, etc.  But not this one.  Thanks for showing us something different, that captures the bird and not the ideal.  10.', '2009-12-07 20:38:56.000000', NULL, 1),
(5758939, 836651, 44877, '<td valign="top">Very pretty. Not sure what the big lump is on the right - maybe I don''t need to know.</td>', 'Very pretty. Not sure what the big lump is on the right - maybe I don''t need to know.', '2009-12-07 20:39:00.000000', NULL, 1),
(5758940, 833091, 70270, '<td valign="top">lovely water and tones.  9</td>', 'lovely water and tones.  9', '2009-12-07 20:39:08.000000', NULL, 1),
(5758941, 836848, 70270, '<td valign="top">beautiful colors, inviting leading lines.  takes me to a road i want to travel.  9</td>', 'beautiful colors, inviting leading lines.  takes me to a road i want to travel.  9', '2009-12-07 20:39:41.000000', NULL, 1),
(5758942, 836820, 44877, '<td valign="top">Outstanding image. First - something different. I''m very excited. Second, most wonderful story telling and editing. So far my fav in this incredibly boring challenge.</td>', 'Outstanding image. First - something different. I''m very excited. Second, most wonderful story telling and editing. So far my fav in this incredibly boring challenge.', '2009-12-07 20:40:04.000000', NULL, 1),
(5758943, 835134, 70270, '<td valign="top">Wonderful detail, light and motion.  9</td>', 'Wonderful detail, light and motion.  9', '2009-12-07 20:40:05.000000', NULL, 1),
(5758944, 831694, 44877, '<td valign="top">Seriously?</td>', 'Seriously?', '2009-12-07 20:40:17.000000', NULL, 1),
(5758945, 832932, 70270, '<td valign="top">Intriguing and effective.  9</td>', 'Intriguing and effective.  9', '2009-12-07 20:40:30.000000', NULL, 1),
(5758946, 836197, 44877, '<td valign="top">Very sweet with the wave, the bird and the sun. Love the minimalism.</td>', 'Very sweet with the wave, the bird and the sun. Love the minimalism.', '2009-12-07 20:40:47.000000', NULL, 1),
(5758949, 836778, 44877, '<td valign="top">Beautiful, dreamy. Interesting perspective, gorgeous tones. Very magical.</td>', 'Beautiful, dreamy. Interesting perspective, gorgeous tones. Very magical.', '2009-12-07 20:41:21.000000', NULL, 1),
(5758950, 836621, 70270, '<td valign="top">Really nice airplane shot, and wonderful post processing treatment.  Not easy to make a shot like this pop, but you did.  9</td>', 'Really nice airplane shot, and wonderful post processing treatment.  Not easy to make a shot like this pop, but you did.  9', '2009-12-07 20:41:30.000000', NULL, 1),
(5758951, 836605, 44877, '<td valign="top">Too cool - the kid''s body language is outstanding. Sweet BW tones.</td>', 'Too cool - the kid''s body language is outstanding. Sweet BW tones.', '2009-12-07 20:42:05.000000', NULL, 1),
(5758952, 836691, 70270, '<td valign="top">Alfred Hitchcock approves.  So do I.  8</td>', 'Alfred Hitchcock approves.  So do I.  8', '2009-12-07 20:42:12.000000', NULL, 1),
(5758954, 836235, 70270, '<td valign="top">Beautiful texture and light.  9</td>', 'Beautiful texture and light.  9', '2009-12-07 20:42:26.000000', NULL, 1),
