(5758956, 836132, 70270, '<td valign="top">wonderfully detailed, and a difficult pic to pull off with this breed.  Reminds me of my old friend.  9</td>', 'wonderfully detailed, and a difficult pic to pull off with this breed.  Reminds me of my old friend.  9', '2009-12-07 20:43:27.000000', NULL, 1),
