(5759469, 832288, 5585, '<td valign="top">Congrats....great landscape</td>', 'Congrats....great landscape', '2009-12-08 00:34:47.000000', NULL, 0),
(5759471, 835189, 83313, '<td valign="top">This was one of my 9''s. The high key works well for it, but mostly, I just love the quirkiness. A shame more didn''t appreciate it. Their loss.</td>', 'This was one of my 9''s. The high key works well for it, but mostly, I just love the quirkiness. A shame more didn''t appreciate it. Their loss.', '2009-12-08 00:36:01.000000', NULL, 0),
(5759474, 832288, 25355, '<td valign="top">Well done and congratulations. Certianly a deserving ribbon-winner.</td>', 'Well done and congratulations. Certianly a deserving ribbon-winner.', '2009-12-08 00:37:59.000000', NULL, 0),
